import java.util.*;
import java.util.stream.Collectors;

// Custom Object class
class CustomObject {
    private String name;
    private int value;

    public CustomObject(String name, int value) {
        this.name = name;
        this.value = value;
    }

    public String getName() {
        return name;
    }

    public int getValue() {
        return value;
    }

    @Override
    public String toString() {
        return name + ": " + value;
    }
}

public class StreamExample {
    public static void main(String[] args) {
        // Create a sample map of Integers to CustomObjects
        Map<Integer, CustomObject> map = new HashMap<>();
        map.put(1, new CustomObject("A", 10));
        map.put(2, new CustomObject("B", 20));
        map.put(3, new CustomObject("C", 30));
        map.put(4, new CustomObject("D", 40));

        // Filter the Map to get only entries where the value is greater than 25
        // Map the entries to CustomObjects
        // Collect the results into a List
        List<CustomObject> filteredList = map.values()
            .stream()
            .filter(obj -> obj.getValue() > 25) // Filter using Predicate
            .map(obj -> obj) // Map to CustomObject
            .collect(Collectors.toList()); // Collect into List

        // Print the result to the console
        System.out.println("Filtered Custom Objects:");
        filteredList.forEach(System.out::println);
    }
}

